package app.kivo.store;
import android.app.*;import android.graphics.*;import android.os.Build;import android.view.*;import android.webkit.WebResourceResponse;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
/** Native viewer: close controls live outside the image, and Back dismisses the dialog. */
final class ScreenshotViewer {
 final MainActivity host;final ExecutorService images=Executors.newFixedThreadPool(2);Dialog dialog;ImageView image;ProgressBar progress;TextView state,title;Button previous,next;JSONObject app;String repo;int index,generation;Future<?> currentTask;float startX,startY;boolean multiTouch;
 ScreenshotViewer(MainActivity activity){host=activity;}
 int dp(int n){return Math.round(n*host.getResources().getDisplayMetrics().density);}
 Button button(String text,String description){Button b=new Button(host);b.setText(text);b.setTextSize(22);b.setTextColor(0xfff3edff);b.setContentDescription(description);b.setMinHeight(dp(48));b.setMinimumWidth(dp(48));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff352c45));return b;}
 void open(String slug,int shot){try{JSONObject a=host.sourceEntry(MainActivity.repo(slug));if(a==null||a.optJSONArray("screenshots")==null||a.optJSONArray("screenshots").length()==0)throw new IOException("No hay capturas disponibles.");close();repo=slug;app=a;index=Math.max(0,Math.min(shot,a.getJSONArray("screenshots").length()-1));dialog=new Dialog(host,android.R.style.Theme_Material_NoActionBar);dialog.setTitle("Capturas de "+a.optString("name"));
 LinearLayout root=new LinearLayout(host);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff14111c);root.setPadding(dp(10),dp(12),dp(10),dp(12));LinearLayout bar=new LinearLayout(host);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),0,0,0);title=new TextView(host);title.setText(a.optString("name"));title.setTextSize(16);title.setTextColor(0xfff4efff);title.setMaxLines(2);bar.addView(title,new LinearLayout.LayoutParams(0,dp(64),1));Button close=button("✕","Cerrar visor de capturas");close.setOnClickListener(v->close());bar.addView(close,new LinearLayout.LayoutParams(dp(56),dp(56)));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(72)));
 FrameLayout stage=new FrameLayout(host);image=new ImageView(host);image.setScaleType(ImageView.ScaleType.FIT_CENTER);stage.addView(image,new FrameLayout.LayoutParams(-1,-1));progress=new ProgressBar(host);FrameLayout.LayoutParams loading=new FrameLayout.LayoutParams(dp(42),dp(42),Gravity.CENTER);stage.addView(progress,loading);root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));
 state=new TextView(host);state.setTextColor(0xffc7bed6);state.setTextSize(12);state.setGravity(Gravity.CENTER);state.setPadding(dp(10),dp(10),dp(10),dp(10));state.setOnClickListener(v->load());root.addView(state,new LinearLayout.LayoutParams(-1,dp(64)));LinearLayout controls=new LinearLayout(host);controls.setGravity(Gravity.CENTER_VERTICAL);previous=button("‹","Captura anterior");next=button("›","Captura siguiente");TextView help=new TextView(host);help.setText("Desliza para ver las demás");help.setGravity(Gravity.CENTER);help.setTextSize(11);help.setTextColor(0xffc7bed6);controls.addView(previous,new LinearLayout.LayoutParams(dp(64),dp(56)));controls.addView(help,new LinearLayout.LayoutParams(0,dp(56),1));controls.addView(next,new LinearLayout.LayoutParams(dp(64),dp(56)));root.addView(controls,new LinearLayout.LayoutParams(-1,dp(64)));previous.setOnClickListener(v->move(-1));next.setOnClickListener(v->move(1));
 image.setOnTouchListener((v,event)->{switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:startX=event.getX();startY=event.getY();multiTouch=false;return true;case MotionEvent.ACTION_POINTER_DOWN:multiTouch=true;return true;case MotionEvent.ACTION_CANCEL:multiTouch=true;return true;case MotionEvent.ACTION_UP:float dx=event.getX()-startX,dy=event.getY()-startY;if(!multiTouch&&Math.abs(dx)>dp(48)&&Math.abs(dx)>Math.abs(dy)*1.3f)move(dx<0?1:-1);v.performClick();return true;default:return true;}});
 dialog.setContentView(root);dialog.setOnDismissListener(d->{generation++;if(image!=null)image.setImageDrawable(null);host.immersive();});dialog.setOnKeyListener((d,key,event)->{if(event.getAction()!=KeyEvent.ACTION_UP)return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT){move(-1);return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT){move(1);return true;}return false;});dialog.show();Window window=dialog.getWindow();if(window!=null){window.setLayout(-1,-1);if(Build.VERSION.SDK_INT>=30){window.setDecorFitsSystemWindows(false);WindowInsetsController c=window.getInsetsController();if(c!=null){c.hide(WindowInsets.Type.systemBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else window.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}load();close.requestFocus();}catch(Exception e){host.status("No se pudo abrir la captura. "+e.getMessage());}}
 void move(int delta){if(dialog==null||!dialog.isShowing())return;int n=Math.max(0,Math.min(index+delta,app.optJSONArray("screenshots").length()-1));if(n!=index){index=n;load();}}
 void load(){if(dialog==null||!dialog.isShowing())return;final int request=++generation,shot=index;final String slug=repo;int count=app.optJSONArray("screenshots").length();previous.setEnabled(index>0);next.setEnabled(index<count-1);previous.setAlpha(index>0?1f:.3f);next.setAlpha(index<count-1?1f:.3f);state.setText((index+1)+" / "+count+" · Cargando…");image.setContentDescription("Captura "+(index+1)+" de "+count+" de "+app.optString("name"));image.setImageDrawable(null);progress.setVisibility(View.VISIBLE);
 if(currentTask!=null)currentTask.cancel(true);currentTask=images.submit(()->{Bitmap bitmap=null;try{WebResourceResponse response=host.mediaResponse(slug,String.valueOf(shot));if(response.getStatusCode()>=400)throw new IOException();byte[] data;try(InputStream in=response.getData();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>6000000)throw new IOException();out.write(b,0,n);}data=out.toByteArray();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>2560)options.inSampleSize*=2;options.inJustDecodeBounds=false;bitmap=BitmapFactory.decodeByteArray(data,0,data.length,options);if(bitmap==null)throw new IOException();}catch(Exception ignored){}final Bitmap result=bitmap;host.runOnUiThread(()->{if(request!=generation||host.isDestroyed()||dialog==null||!dialog.isShowing()){if(result!=null)result.recycle();return;}progress.setVisibility(View.GONE);if(result==null)state.setText((shot+1)+" / "+count+" · No se pudo cargar. Toca aquí para reintentar.");else{image.setImageBitmap(result);state.setText((shot+1)+" / "+count);}});});}
 void close(){generation++;if(currentTask!=null){currentTask.cancel(true);currentTask=null;}if(dialog!=null){dialog.dismiss();dialog=null;}}
 void destroy(){close();images.shutdownNow();}
}
